import json, collections
d = json.loads(open('graphify-out/graph.json', encoding='utf-8').read())
nodes = {n['id']: n for n in d['nodes']}
links = d['links']

internal_funcs = {nid: n for nid, n in nodes.items() if (n.get('source_file') or '').startswith('internal/') and n.get('label','').endswith('()')}
print('count internal function/method nodes:', len(internal_funcs))

fanin = collections.Counter()
for l in links:
    if l.get('relation') in ('calls','indirect_call'):
        t = l.get('target')
        if t in internal_funcs:
            fanin[t]+=1

top = fanin.most_common(25)
for nid, c in top:
    n = nodes[nid]
    print(c, nid, n.get('label'), n.get('source_file'), n.get('source_location'))
"
